const pc=createPCBridge();
const loaded=loadState();let state=loaded.state;
const controller=new AbortController();const signal=controller.signal;
let toastTimer=null,bootTimer=null,clockTimer=null,modalPending=false;
const $=id=>document.getElementById(id);
function notify(message){$('toast').textContent=message;$('toast').hidden=false;if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('toast').hidden=true;toastTimer=null;},4500);}
const autosave=createAutosave(()=>state,notify);
const vfs=createFileSystem(state,()=>autosave.schedule());
// Browser-local filesystem keeps the same state identity; all persisted settings are validated.
function applySettings(){window.dispatchEvent(new Event('retro-settings-change'));document.body.dataset.theme=state.settings.theme;document.documentElement.style.setProperty('--desktop',state.settings.background);document.documentElement.style.setProperty('--icon-size',state.settings.iconSize+'px');document.body.classList.toggle('no-animation',!state.settings.animations);$('volume-button').title=state.settings.muted?'소리 꺼짐 · 설정 열기':'소리 설정 열기';updateClock();}
function saveSettings(patch){try{const candidate=normalizeState({...state,settings:{...state.settings,...patch}});Object.assign(state.settings,candidate.settings);applySettings();if(patch.autoArrange!==undefined)layoutDesktopIcons();autosave.schedule();}catch(e){notify(e.message);}}
function updateClock(){const now=new Date();$('clock').textContent=new Intl.DateTimeFormat('ko-KR',{hour:'numeric',minute:'2-digit',hour12:!state.settings.hour24}).format(now);$('clock').dateTime=now.toISOString();$('clock').title=new Intl.DateTimeFormat('ko-KR',{dateStyle:'full'}).format(now);}
function stopClock(){if(clockTimer!==null)clearInterval(clockTimer);clockTimer=null;}
function startClock(){updateClock();if(clockTimer===null&&!document.hidden)clockTimer=setInterval(updateClock,30000);}
function download(name,content,mime='text/plain'){const blob=content instanceof Blob?content:new Blob([content],{type:mime});const url=URL.createObjectURL(blob);const a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function modal({title='RETRO OS',message='',input=false,defaultValue='',confirmText='확인',cancelText='취소'}={}){
 if(modalPending)return null;modalPending=true;const previous=document.activeElement;const dialog=$('system-dialog');$('dialog-title').textContent=title;$('dialog-message').textContent=message;$('dialog-icon').innerHTML=icon('welcome',32);const field=$('dialog-input');field.hidden=!input;field.value=defaultValue;$('dialog-confirm').textContent=confirmText;$('dialog-cancel').textContent=cancelText;dialog.returnValue='';
 return new Promise(resolve=>{const done=()=>{const result=dialog.returnValue==='confirm'?(input?field.value:true):null;dialog.removeEventListener('close',done);modalPending=false;if(previous?.isConnected)previous.focus();resolve(result);};dialog.addEventListener('close',done);dialog.showModal();if(input){field.focus();field.select();}else $('dialog-confirm').focus();});
}
$('system-dialog').querySelector('form').addEventListener('submit',e=>{e.preventDefault();$('system-dialog').close('confirm');},{signal});$('dialog-cancel').addEventListener('click',()=>$('system-dialog').close('cancel'),{signal});
function exportBackup(){autosave.flush();try{download('retro-os-backup.json',exportState(state),'application/json');notify('가상 파일과 설정을 백업했습니다.');}catch(e){notify(e.message);}}
async function replaceState(next){
 // Validation and a dirty check happen before any state or window changes.
 const validated=normalizeState(next);
 for(const s of wm.windows.values())if(s.dirty){if(!await modal({title:'열려 있는 변경사항',message:'저장하지 않은 작업이 있습니다. 백업을 적용하면 열린 프로그램이 닫힙니다. 계속할까요?',confirmText:'계속',cancelText:'취소'}))return false;break;}
 for(const id of [...wm.windows.keys()])await wm.closeWindow(id,true);
 state.version=validated.version;state.nodes=validated.nodes;state.settings=validated.settings;state.iconPositions=validated.iconPositions;
 applySettings();renderIcons();autosave.schedule();autosave.flush();openApp('welcome');return true;
}
async function importBackup(file){try{if(file.size>LIMITS.backupBytes)throw new Error('백업 파일은 2MB 이하여야 합니다.');if(file.type&&!['application/json','text/plain',''].includes(file.type)&&!file.name.toLowerCase().endsWith('.json'))throw new Error('JSON 백업 파일을 선택하세요.');const next=parseBackup(await file.text());if(!await modal({title:'백업 가져오기',message:'현재 가상 파일과 설정을 선택한 백업으로 바꿀까요? 현재 데이터는 덮어씁니다.',confirmText:'가져오기',cancelText:'취소'}))return;if(await replaceState(next))notify('백업을 복원했습니다.');}catch(e){notify(e.message);}}
function openApp(type,options={}){closeMenus();const id=wm.openWindow(type,options);if(!id&&type==='pc-editor'&&options.document?.id)pc.request('/files/release',{id:options.document.id}).catch(()=>{});return id;}
function makeServices(windowState){return {vfs,pc,frame:windowState.element,openApp,modal,notify,get settings(){return state.settings;},getSettings:()=>state.settings,saveSettings,icon,download,exportBackup,importBackup,resetData:async()=>{if(await replaceState(createInitialState()))notify('기본 바탕화면으로 되돌렸습니다.');}};}
function createWelcomeApp(){let abort;return {mount(container,services){abort=new AbortController();const tabs=el('div','welcome-tabs');const panel=el('div','welcome-panel system-properties');tabs.setAttribute('role','tablist');panel.setAttribute('role','tabpanel');container.append(tabs,panel);let selected='about';const render=()=>{panel.replaceChildren();for(const b of tabs.children){b.classList.toggle('active',b.dataset.tab===selected);b.setAttribute('aria-selected',String(b.dataset.tab===selected));}if(selected==='about'){panel.innerHTML=`<div class="properties-header">${icon('computer',64)}<div><h1>RETRO OS 98</h1><p>Personal Edition</p><p>버전 1.0</p></div></div><hr><dl class="properties-list"><dt>저장 위치</dt><dd>브라우저 로컬 저장소</dd><dt>파일 제한</dt><dd>600개 / 8단계 / 파일당 256KB</dd><dt>백업 형식</dt><dd>JSON · 최대 2MB</dd><dt>열린 창</dt><dd>최대 12개</dd></dl>`;}else{panel.innerHTML=`<div class="properties-help"><p>아이콘을 두 번 클릭하면 실행됩니다.<br>터치 화면에서는 한 번 누르세요.</p><dl><dt>Ctrl + S</dt><dd>메모장 저장</dd><dt>Ctrl + Z</dt><dd>실행 취소</dd><dt>F2</dt><dd>파일 이름 바꾸기</dd><dt>Delete</dt><dd>휴지통으로 이동</dd><dt>Esc</dt><dd>메뉴 · 대화상자 닫기</dd></dl><p>파일과 설정은 자동 저장됩니다.<br>그림판의 그림은 PNG로 저장하세요.</p><p>새로고침 시 열린 창은 닫힙니다.</p></div>`;}};for(const [id,label]of [['about','일반'],['help','도움말']]){const b=el('button','welcome-tab',label);b.dataset.tab=id;b.setAttribute('role','tab');b.addEventListener('click',()=>{selected=id;render();},{signal:abort.signal});tabs.append(b);}render();},unmount(){abort?.abort();}};}
const wm=new WindowManager({layer:$('window-layer'),taskbar:$('task-buttons'),createApp:(type,options)=>type==='loading'?createDesktopLoader():type==='pc'||type==='pc-editor'?createPCApp(type,options):type==='welcome'?createWelcomeApp():['explorer','notepad','terminal'].includes(type)?createTextApp(type,options):createExtraApp(type,options),makeServices,onError:notify});
const desktopApps=[['computer','내 컴퓨터','pc',{}],['documents','내 문서','explorer',{folderId:'documents'}],['notepad','메모장','notepad',{}],['paint','그림판','paint',{}],['mines','지뢰찾기','mines',{}],['terminal','명령 프롬프트','terminal',{}],['trash','휴지통','explorer',{folderId:'trash'}],['settings','설정','settings',{}]];
let iconsAbort;const selectedIcons=new Set();
function setDesktopSelection(ids){selectedIcons.clear();for(const id of ids)selectedIcons.add(id);for(const b of $('desktop-icons').children){const selected=selectedIcons.has(b.dataset.icon);b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));}}
function layoutDesktopIcons(){const desktop=$('desktop');const positions=arrangeDesktopIcons(desktopApps.length,desktop.clientWidth,desktop.clientHeight);[...$('desktop-icons').children].forEach((b,i)=>{const position=state.settings.autoArrange?positions[i]:(state.iconPositions[b.dataset.icon]||positions[i]);b.style.left=Math.max(0,Math.min(desktop.clientWidth-88,position.x))+'px';b.style.top=Math.max(0,Math.min(desktop.clientHeight-96,position.y))+'px';});}
function renderIcons(){iconsAbort?.abort();iconsAbort=new AbortController();$('desktop-icons').replaceChildren();for(const [name,label,type,options]of desktopApps){const b=el('button','desktop-icon');b.dataset.icon=name;b.innerHTML=icon(name,40);b.append(el('span','desktop-icon-label',label));b.title=label+' 열기';let moved=false;
 b.addEventListener('click',e=>{if(moved)return;if(e.ctrlKey||e.metaKey){const next=new Set(selectedIcons);if(next.has(name))next.delete(name);else next.add(name);setDesktopSelection(next);}else if(e.shiftKey)setDesktopSelection([...selectedIcons,name]);else setDesktopSelection([name]);if(matchMedia('(pointer: coarse)').matches)openApp(type,options);},{signal:iconsAbort.signal});
 b.addEventListener('dblclick',()=>{if(!moved)openApp(type,options);},{signal:iconsAbort.signal});b.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();openApp(type,options);}},{signal:iconsAbort.signal});
 b.addEventListener('contextmenu',e=>{e.preventDefault();e.stopPropagation();if(!selectedIcons.has(name))setDesktopSelection([name]);showContext(e.clientX,e.clientY,[['열기',()=>openApp(type,options)],[state.settings.autoArrange?'✓ 아이콘 자동 정렬':'아이콘 자동 정렬',toggleAutoArrange],['디스플레이 설정',()=>openApp('settings')]]);},{signal:iconsAbort.signal});
 bindPointer(b,{signal:iconsAbort.signal,start:e=>{moved=false;if(e.pointerType==='touch')return false;const chosen=selectedIcons.has(name)?new Set(selectedIcons):new Set(e.ctrlKey||e.metaKey?[...selectedIcons,name]:[name]);const bounds=$('desktop').getBoundingClientRect();const items=[...$('desktop-icons').children].filter(item=>chosen.has(item.dataset.icon)).map(item=>{const r=item.getBoundingClientRect();return {element:item,x:r.x-bounds.x,y:r.y-bounds.y};});return {px:e.clientX,py:e.clientY,chosen,items};},move:(e,d)=>{if(Math.hypot(e.clientX-d.px,e.clientY-d.py)<5&&!moved)return;moved=true;setDesktopSelection(d.chosen);const desktop=$('desktop');const minX=Math.min(...d.items.map(i=>i.x)),minY=Math.min(...d.items.map(i=>i.y)),maxX=Math.max(...d.items.map(i=>i.x+88)),maxY=Math.max(...d.items.map(i=>i.y+96));const dx=Math.max(-minX,Math.min(desktop.clientWidth-maxX,e.clientX-d.px)),dy=Math.max(-minY,Math.min(desktop.clientHeight-maxY,e.clientY-d.py));for(const item of d.items){item.element.style.left=item.x+dx+'px';item.element.style.top=item.y+dy+'px';}},end:(e,d)=>{if(!moved)return;if(!state.settings.autoArrange){for(const item of d.items)state.iconPositions[item.element.dataset.icon]={x:parseFloat(item.element.style.left),y:parseFloat(item.element.style.top)};autosave.schedule();}layoutDesktopIcons();setTimeout(()=>moved=false,100);}});
 $('desktop-icons').append(b);}layoutDesktopIcons();setDesktopSelection(new Set(selectedIcons));}
function arrangeIcons(){state.iconPositions={};saveSettings({autoArrange:true});layoutDesktopIcons();}
function toggleAutoArrange(){if(state.settings.autoArrange)saveSettings({autoArrange:false});else arrangeIcons();}
const selectionBox=el('div','desktop-selection-box');selectionBox.hidden=true;selectionBox.setAttribute('aria-hidden','true');$('desktop').append(selectionBox);$('desktop').tabIndex=-1;
bindPointer($('desktop'),{signal,start:e=>{if(e.target.closest('.desktop-icon,.os-window,button,input,textarea,select')||e.pointerType==='touch')return false;const bounds=$('desktop').getBoundingClientRect();const original=new Set(selectedIcons),base=e.ctrlKey||e.metaKey||e.shiftKey?original:new Set();setDesktopSelection(base);$('desktop').focus({preventScroll:true});closeMenus();return {start:{x:e.clientX-bounds.x,y:e.clientY-bounds.y},bounds,base,original,items:[...$('desktop-icons').children].map(b=>{const r=b.getBoundingClientRect();return {id:b.dataset.icon,x:r.x-bounds.x,y:r.y-bounds.y,width:r.width,height:r.height};})};},move:(e,d)=>{const rect=selectionBounds(d.start,{x:e.clientX-d.bounds.x,y:e.clientY-d.bounds.y});if(rect.width<4&&rect.height<4)return;selectionBox.hidden=false;Object.assign(selectionBox.style,{left:rect.x+'px',top:rect.y+'px',width:rect.width+'px',height:rect.height+'px'});setDesktopSelection(collectSelected(rect,d.items,d.base));},end:(e,d)=>{selectionBox.hidden=true;if(e.type==='pointercancel')setDesktopSelection(d.original);}});
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'&&!document.activeElement?.closest('.os-window,input,textarea,[contenteditable=true]')){e.preventDefault();setDesktopSelection(desktopApps.map(a=>a[0]));}if(e.key==='Escape'&&!document.activeElement?.closest('input,textarea'))setDesktopSelection([]);},{signal});
function closeMenus(){for(const menu of document.querySelectorAll('.start-submenu'))menu.hidden=true;for(const b of document.querySelectorAll('.start-folder'))b.setAttribute('aria-expanded','false');const open=!$('start-menu').hidden;$('start-menu').hidden=true;$('start-button').setAttribute('aria-expanded','false');$('context-menu').hidden=true;if(open)$('start-button').classList.remove('active');}
function showContext(x,y,items){closeMenus();const menu=$('context-menu');menu.replaceChildren();for(const [label,action]of items){const b=el('button','',label);b.addEventListener('click',()=>{closeMenus();action();},{once:true});menu.append(b);}menu.hidden=false;menu.style.left=Math.max(0,Math.min(x,innerWidth-menu.offsetWidth-5))+'px';menu.style.top=Math.max(0,Math.min(y,innerHeight-menu.offsetHeight-45))+'px';menu.querySelector('button')?.focus();}
$('start-logo').innerHTML=icon('start',24);$('show-desktop').innerHTML=icon('computer',24);$('volume-button').innerHTML=icon('sound',20);
const programItems=[['notepad','메모장','notepad'],['paint','그림판','paint'],['mines','지뢰찾기','mines'],['terminal','MS-DOS 프롬프트','terminal']];
function startEntry(label,name,action,parent=$('start-items')){const b=el('button','start-item');b.setAttribute('role','menuitem');b.innerHTML=icon(name,28);b.append(el('span','',label));b.addEventListener('click',action,{signal});parent.append(b);return b;}
function startGroup(label,name,items){const wrapper=el('div','start-group');const popup=el('div','start-submenu');popup.setAttribute('role','menu');popup.setAttribute('aria-label',label);popup.hidden=true;const b=startEntry(label,name,()=>{const show=popup.hidden;for(const p of document.querySelectorAll('.start-submenu'))p.hidden=true;for(const p of document.querySelectorAll('.start-folder'))p.setAttribute('aria-expanded','false');popup.replaceChildren();for(const [title,ico,action]of items())startEntry(title,ico,action,popup);popup.hidden=!show;b.setAttribute('aria-expanded',String(show));if(show)popup.querySelector('button')?.focus();},wrapper);b.classList.add('start-folder');b.setAttribute('aria-haspopup','menu');b.setAttribute('aria-expanded','false');b.append(el('i','submenu-arrow',''));wrapper.append(popup);$('start-items').append(wrapper);}
startGroup('프로그램','folder',()=>programItems.map(([type,title,ico])=>[title,ico,()=>openApp(type)]));
startGroup('문서','documents',()=>{const docs=vfs.list('documents').filter(n=>n.type==='text').slice(0,6);return [...docs.map(n=>[n.name,'text',()=>openApp('notepad',{fileId:n.id})]),['내 문서','folder',()=>openApp('explorer',{folderId:'documents'})]];});
startGroup('설정','settings',()=>[['디스플레이','settings',()=>openApp('settings')],['시스템 등록 정보','computer',()=>openApp('welcome')],['로딩 창','welcome',()=>openApp('loading')],['가상 디스크 백업','floppy',()=>{closeMenus();exportBackup();}]]);
$('start-items').append(el('div','menu-divider'));
startEntry('내 컴퓨터','computer',()=>openApp('pc'));
startEntry('가상 디스크 (R:)','drive',()=>openApp('explorer',{folderId:'root'}));
startEntry('실행...','run',async()=>{closeMenus();const command=await modal({title:'실행',message:'프로그램 이름을 입력하세요.',input:true,defaultValue:'notepad',confirmText:'확인'});if(typeof command!=='string')return;const apps={notepad:'notepad',mspaint:'paint',winmine:'mines',cmd:'terminal',explorer:'explorer',control:'settings',computer:'pc'};const app=apps[command.trim().toLowerCase()];if(app)openApp(app);else notify('notepad, mspaint, winmine, cmd, explorer, control, computer 중 하나를 입력하세요.');});
$('start-items').append(el('div','menu-divider'));
startEntry('다시 시작...','restart',async()=>{closeMenus();if(!await modal({title:'RETRO OS 다시 시작',message:'열린 프로그램을 닫고 RETRO OS를 다시 시작할까요?',confirmText:'다시 시작'}))return;for(const id of [...wm.windows.keys()])if(!await wm.closeWindow(id))return;autosave.flush();$('boot-screen').hidden=false;bootTimer=setTimeout(finishBoot,1500);});
$('start-button').addEventListener('click',()=>{const wasOpen=!$('start-menu').hidden;closeMenus();if(!wasOpen){$('start-menu').hidden=false;$('start-button').setAttribute('aria-expanded','true');$('start-button').classList.add('active');$('start-items').querySelector('button').focus();}},{signal});
$('start-menu').addEventListener('keydown',e=>{const buttons=[...$('start-menu').querySelectorAll('button')].filter(b=>!b.closest('[hidden]'));const i=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[next]?.focus();}if(e.key==='ArrowRight'&&document.activeElement.classList.contains('start-folder')){e.preventDefault();document.activeElement.click();}if(e.key==='ArrowLeft'){const popup=document.activeElement.closest('.start-submenu');if(popup){popup.hidden=true;popup.previousElementSibling?.focus();popup.previousElementSibling?.setAttribute('aria-expanded','false');}}},{signal});
$('show-desktop').addEventListener('click',()=>{for(const id of wm.windows.keys())wm.minimizeWindow(id);},{signal});$('volume-button').addEventListener('click',()=>openApp('settings'),{signal});
$('desktop').addEventListener('contextmenu',e=>{if(e.target.closest('.os-window,.desktop-icon'))return;e.preventDefault();showContext(e.clientX,e.clientY,[['새 텍스트 문서',()=>openApp('notepad')],['로딩 창',()=>openApp('loading')],[state.settings.autoArrange?'✓ 아이콘 자동 정렬':'아이콘 자동 정렬',toggleAutoArrange],['바탕화면 새로고침',()=>{renderIcons();notify('바탕화면을 새로고침했습니다.');}],['디스플레이 설정',()=>openApp('settings')]]);},{signal});
window.addEventListener('pointerdown',e=>{if(!e.target.closest('#start-menu,#start-button,#context-menu'))closeMenus();},{signal});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenus();if(!$('system-dialog').open)$('start-button').focus();}},{signal});
window.addEventListener('resize',layoutDesktopIcons,{signal});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopClock();autosave.flush();}else startClock();},{signal});window.addEventListener('pagehide',()=>{stopClock();autosave.flush();},{signal});window.addEventListener('pageshow',startClock,{signal});window.addEventListener('focus',updateClock,{signal});
