window.retroOS={wm,vfs,getState:()=>state,openApp,exportBackup,importBackup,clock:()=>({active:clockTimer!==null,text:$('clock').textContent}),destroy:async()=>{if(bootTimer)clearTimeout(bootTimer);if(toastTimer)clearTimeout(toastTimer);stopClock();autosave.destroy();iconsAbort?.abort();controller.abort();selectionBox.remove();await wm.destroy();releaseCatImages();vfs.destroy();}};
